Lemma rin_ivs_elemsW : forall L a, rin_ivs (elemsW L) a <-> exists e, In e L /\ e <= a < e + 48.
Proof.
  intros L a. induction L as [|e L IH]; cbn.
  - split; [tauto | intros (e & F & _); exact F].
  - rewrite IH. split.
    + intros [K | (e' & I & K)]; [exists e; auto | exists e'; auto].
    + intros (e' & [<- | I] & K); [left; exact K | right; exists e'; auto].
Qed.

Lemma lb_bytes_app : forall l1 l2, lb_bytes (l1 ++ l2) = lb_bytes l1 + lb_bytes l2.
Proof. intros l1 l2. induction l1 as [|b l1 IH]; [reflexivity|]. cbn [app]. rewrite !lb_bytes_cons, IH. lia. Qed.

