Definition elems_heap (em : gmap Z elt) : Prop :=
  forall e d, em !! e = Some d -> e + esize d <= 0x10000 \/ 0xb8000 <= e.

Definition pstaticW (Fa : Z) (W : list (Z * Z)) : Prop :=
  Forall (fun iv : Z * Z => (hceil <= fst iv /\ (snd iv <= Fa \/ Fa + 48 <= fst iv)) \/ (0x10000 <= fst iv /\ snd iv <= 0xb8000)) W.

Lemma pstaticW_disjoint_elem : forall Fa W a n e sz,
  pstaticW Fa W -> e <= a -> a + n <= e + sz -> e + sz <= hceil -> (e + sz <= 0x10000 \/ 0xb8000 <= e) -> disjoint_from W a n.
Proof.
  intros Fa W a n e sz F H1 H2 H3 H4. induction W as [|[lo hi] W IH]; [exact I|]. cbn.
  pose proof (Forall_inv F) as K. cbn in K. split; [lia| apply IH; exact (Forall_inv_tail F)].
Qed.

Lemma pstaticW_disjoint_hdr : forall Fa W a n, pstaticW Fa W -> Fa <= a -> a + n <= Fa + 48 -> 0xb8000 <= Fa -> disjoint_from W a n.
Proof.
  intros Fa W a n F H1 H2 GE. induction W as [|[lo hi] W IH]; [exact I|]. cbn.
  pose proof (Forall_inv F) as K. cbn in K. split; [lia| apply IH; exact (Forall_inv_tail F)].
Qed.
