(* [comment removed for export] *)
(* [comment removed for export] *)
Definition elems_ok (L : list Z) : Prop :=
  forall e, e ∈ L -> 0 < e /\ e + 48 <= hceil /\ (e + 48 <= 0x10000 \/ 0xb8000 <= e).

Lemma elemsW_hi : forall L A n, elems_ok L -> hceil <= A -> Forall (fun iv : Z * Z => A + n <= fst iv \/ snd iv <= A) (elemsW L).
Proof.
  intros L A n EL HA. apply Forall_forall. intros [u v] INuv. apply in_map_iff in INuv. destruct INuv as (a & Euv & INa).
  injection Euv as <- <-. cbn. destruct (EL a ltac:(apply (proj2 (list_elem_of_In _ _)); exact INa)) as (K1 & K2 & K3). lia.
Qed.

Lemma elemsW_statics : forall L, elems_ok L -> xoff_statics (elemsW L).
Proof.
  intros L EL. apply Forall_forall. intros [u v] INuv. apply in_map_iff in INuv. destruct INuv as (a & Euv & INa).
  injection Euv as <- <-. cbn. destruct (EL a ltac:(apply (proj2 (list_elem_of_In _ _)); exact INa)) as (K1 & K2 & K3). lia.
Qed.

Lemma elemsW_win : forall L p0 n, (forall e, e ∈ L -> e + 48 <= p0 \/ p0 + n <= e) ->
  Forall (fun iv : Z * Z => p0 + n <= fst iv \/ snd iv <= p0) (elemsW L).
Proof.
  intros L p0 n WL. apply Forall_forall. intros [u v] INuv. apply in_map_iff in INuv. destruct INuv as (a & Euv & INa).
  injection Euv as <- <-. cbn. destruct (WL a ltac:(apply (proj2 (list_elem_of_In _ _)); exact INa)); lia.
Qed.

Definition IPF_STACK : Z := IPF_FRAME + OTF_STACK.

(* [comment removed for export] *)
Definition ipf_X (P IN E : Z) (L0 : list Z) : list (Z * Z) :=
  (P, P + 128) :: (IN, IN + 8) :: (E, E + 24) :: (G_HTTP_CAT, G_HTTP_CAT + 64) :: (G_FIELD_TABLE, G_FIELD_TABLE + 3456) :: elemsW L0.

(* [comment removed for export] *)
Definition new_elems_off (LB0 : list block) (SP : Z) (L0 L1 : list Z) : Prop :=
  forall e, e ∈ L1 -> e ∈ L0 \/ (forall a k, rclient_range LB0 SP a k -> 0 <= k -> a + k <= e \/ e + 48 <= a).

(* [comment removed for export] *)
Definition lsub (L0 L1 : list Z) : Prop := forall e, e ∈ L0 -> e ∈ L1.
Definition lbn_own (L1 : list Z) (LBn : list block) : Prop := forall b, In b LBn -> blk_addr b ∈ L1 /\ 1 <= blk_size b.

Lemma lsub_refl : forall L, lsub L L.
Proof. intros L e He. exact He. Qed.
Lemma lbn_own_nil : forall L, lbn_own L [].
Proof. intros L b Hb. destruct Hb. Qed.

