Definition ipf_after_cb (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (m0 : mem) (mo0 : Model) (LB0 : list block) (P IN E lo B : Z) (c0 : pcore) (pad7 pad2 : list byte) (p0 : Z) (bs : list byte)
    (L0 : list Z) (mb : byte) (p' : Z) (cf : config) : Prop :=
  exists (rax t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s6x s7x t3 t4 t5 t6 : word) (m3 : mem) (c2 : pcore) (g1 : bool) (q bsz : Z) (j16 jt bb : list byte)
         (vl nm : list cell) (st3 : PState) (LBn : list block) (S1 L1 : list Z) (ns1 : NS) (ls1 : LS) (em1 : gmap Z elt) (errv1 : word),
    cfg_ms cf = MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -4288)) gp tp t0 t1 t2 (wz E) (wz IN)
                     a0 a1 a2 a3 a4 a5 a6 a7
                     (wz (p0 + Z.of_nat (length bs))) (wz P) (wz G_FIELD_TABLE_GUARD) (wz G_FIELD_TABLE) s6x s7x
                     (Z_to_bv 64 (bv_unsigned sp + -128)) (wz 2) (wz 1) (wz 10) t3 t4 t5 t6)
                F (Z_to_bv 64 IPF_VRET) fc None m3 (seg_rom usegs)
    /\ hs_KREL H st3 (cfg_model cf) /\ hs_MPRES H mo0 (cfg_model cf)
    /\ mem_inv usegs m3 /\ stk usegs m3 lo (bv_unsigned sp + -4288)
    /\ rw_cells usegs m3 (errno_addr tp) [C4 errv1] /\ hs_rauxv_ok H m3 B
    /\ hs_RHEAP H st3 (LBn ++ LB0) m3
    /\ FieldsC m3 (P + 80) S1 L1 ns1 ls1 em1 /\ FieldsOwn (LBn ++ LB0) em1 /\ new_elems_off LB0 (bv_unsigned sp) L0 L1
    /\ lsub L0 L1 /\ lbn_own L1 LBn
    /\ (forall e, e ∈ L1 -> e + 48 <= p0 \/ p0 + Z.of_nat (length bs) <= e)
    /\ xpres LB0 (bv_unsigned sp) (ipf_X P IN E L0) m0 m3
    /\ lb_bytes LBn <= 17 * (p' - p0) /\ 4 * Z.of_nat (length LBn) <= p' - p0
    /\ ipf_frame m3 sp j16 jt p' bsz bb vl nm
    /\ rw_cells usegs m3 (bv_unsigned sp + -104) (map C8 (ipf_sv s11 s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra))
    /\ rw_cells usegs m3 P (ParserCoreCells c2 pad7 pad2) /\ dof_core c0 c2
    /\ rw_cells usegs m3 IN [C8 (wz q)]
    /\ rw_cells usegs m3 E (ErrCodeCells EC_clear) /\ rw_cells usegs m3 (P + 242) [C1 mb]
    /\ bytes_at usegs m3 p0 bs /\ PfTab m3 /\ FT m3 /\ FTInit m3 /\ HttpCat m3 g1 /\ XStatics m3
    /\ p0 <= p' /\ p' + 1 <= p0 + Z.of_nat (length bs).


