Definition ipf_static (sp : word) (tp : word) (LB0 : list block) (P IN E lo B : Z) (c0 : pcore) (p0 : Z) (bs : list byte) (mb : byte) : Prop :=
  ipf_pure sp P IN E lo c0 p0 bs
  /\ rclient_range LB0 (bv_unsigned sp) p0 (Z.of_nat (length bs))
  /\ lb_bytes LB0 + 17 * Z.of_nat (length bs) <= hs_LIVE_MAX H /\ Z.of_nat (length LB0) + Z.of_nat (length bs) / 4 <= hs_LIVE_CNT_MAX H
  /\ bv_unsigned sp <= B /\ P + 256 <= B /\ IN + 8 <= B /\ E + 24 <= B /\ B <= 2^64
  /\ hceil <= lo /\ lo <= bv_unsigned sp - IPF_STACK /\ tp = Z_to_bv 64 RATP /\ bv_unsigned mb <= 1.

